import unittest
from candidate import all_prefixes


class TestAllPrefixes(unittest.TestCase):
    def test_all_prefixes_normal_string(self):
        self.assertEqual(all_prefixes('abc'), ['a', 'ab', 'abc'])

    def test_all_prefixes_single_character(self):
        self.assertEqual(all_prefixes('x'), ['x'])

    def test_all_prefixes_empty_string(self):
        self.assertEqual(all_prefixes(''), [])

    def test_all_prefixes_unicode_string(self):
        self.assertEqual(all_prefixes('éß'), ['é', 'éß'])

    def test_all_prefixes_long_string(self):
        long_str = 'a' * 1000
        prefixes = all_prefixes(long_str)
        self.assertEqual(len(prefixes), 1000)
        self.assertEqual(prefixes[-1], long_str)

    def test_all_prefixes_whitespace_and_special(self):
        s = ' a\nb'
        expected = [' ', ' a', ' a\n', ' a\nb']
        self.assertEqual(all_prefixes(s), expected)

    def test_all_prefixes_type_error_none(self):
        with self.assertRaises(TypeError):
            all_prefixes(None)

    def test_all_prefixes_type_error_int(self):
        with self.assertRaises(TypeError):
            all_prefixes(123)

    def test_all_prefixes_type_error_list(self):
        with self.assertRaises(TypeError):
            all_prefixes(['a', 'b'])

    def test_all_prefixes_output_is_new_list(self):
        s = 'test'
        first = all_prefixes(s)
        second = all_prefixes(s)
        self.assertIsNot(first, second)
        first[0] = 'modified'
        self.assertNotEqual(first[0], second[0])
        self.assertEqual(second[0], 't')

    def test_all_prefixes_prefix_order(self):
        s = 'abcd'
        prefixes = all_prefixes(s)
        for i in range(len(prefixes) - 1):
            self.assertLess(len(prefixes[i]), len(prefixes[i + 1]))

    def test_all_prefixes_output_elements_type(self):
        s = 'abc'
        prefixes = all_prefixes(s)
        for prefix in prefixes:
            self.assertIsInstance(prefix, str)

    def test_all_prefixes_no_empty_prefix(self):
        self.assertNotIn('', all_prefixes('abc'))

    def test_all_prefixes_bytes_input(self):
        b = b'abc'
        prefixes = all_prefixes(b)
        self.assertEqual([type(p) for p in prefixes], [bytes, bytes, bytes])
        self.assertEqual(prefixes, [b'a', b'ab', b'abc'])

    def test_all_prefixes_null_character(self):
        s = 'a\0b'
        self.assertEqual(all_prefixes(s), ['a', 'a\0', 'a\0b'])

    def test_all_prefixes_repeated_characters(self):
        s = 'aaa'
        self.assertEqual(all_prefixes(s), ['a', 'aa', 'aaa'])

    def test_all_prefixes_modifying_result_does_not_affect_original(self):
        original = 'xyz'
        prefixes = all_prefixes(original)
        prefixes[1] = 'modified'
        self.assertEqual(original, 'xyz')

    def test_all_prefixes_consistent_with_manual_calculation(self):
        s = 'python'
        manual = []
        for i in range(len(s)):
            manual.append(s[: i + 1])
        self.assertEqual(all_prefixes(s), manual)


if __name__ == '__main__':
    unittest.main()
